'use strict';

const fs = require('fs');
const path = require('path');

const sources = ['a.txt', 'b.txt', 'c.txt'];
const ROOT = __dirname;

function parsePopulation(file) {
  const full = path.join(ROOT, file);
  const raw = fs.readFileSync(full, 'utf8');
  const text = raw.trim();
  const m = text.match(/^([A-Za-z]+)\s+population:\s*(-?\d+)$/);
  if (!m) {
    throw new Error(`Unrecognised population line in ${full}: ${JSON.stringify(raw)}`);
  }
  const value = Number(m[2]);
  if (!Number.isInteger(value)) {
    throw new Error(`Non-integer population in ${full}: ${m[2]}`);
  }
  if (value < 0) {
    throw new Error(`Negative population in ${full}: ${m[2]}`);
  }
  return { file, full, label: m[1], value };
}

const entries = sources.map(parsePopulation);

// Cross-checks: three distinct labels, three distinct source files, positive counts.
const labels = new Set(entries.map((e) => e.label));
if (labels.size !== sources.length) {
  throw new Error(`Duplicate population labels across sources: ${entries.map((e) => e.label).join(', ')}`);
}
for (const e of entries) {
  console.log(`SOURCE ${e.full} -> label=${e.label} population=${e.value}`);
}

const total = entries.reduce((acc, e) => acc + e.value, 0);

// Independent re-computation as a second cross-check of the sum.
let manual = 0;
for (const value of [entries[0].value, entries[1].value, entries[2].value]) {
  manual += value;
}
if (manual !== total) {
  throw new Error(`Sum mismatch: reduce=${total} manual=${manual}`);
}

const outPath = path.join(ROOT, 'answer.json');
fs.writeFileSync(outPath, JSON.stringify({ total }, null, 2) + '\n', 'utf8');

// Verification of what was actually written to disk.
const written = JSON.parse(fs.readFileSync(outPath, 'utf8'));
if (typeof written.total !== 'number') {
  throw new Error(`answer.json total is not numeric: ${typeof written.total}`);
}
if (written.total !== total) {
  throw new Error(`answer.json total=${written.total} does not match computed sum=${total}`);
}
if (Object.keys(written).length !== 1 || Object.keys(written)[0] !== 'total') {
  throw new Error(`answer.json keys unexpected: ${JSON.stringify(Object.keys(written))}`);
}

console.log(`SUCCESS total=${total} written to ${outPath}`);

