const fs=require("fs");
let sum=0; const rows=[];
for (const f of ["a.txt","b.txt","c.txt"]) {
  const raw=fs.readFileSync(f,"utf8");
  const m=raw.trim().match(/^([A-Za-z]+)\s+population:\s*(\d+)$/);
  if(!m) throw new Error("unparsable "+f+": "+JSON.stringify(raw));
  const v=Number(m[2]);
  if(!Number.isInteger(v)||v<0) throw new Error("bad value in "+f);
  rows.push({file:f,label:m[1],value:v,bytes:raw.length});
  sum+=v;
}
const labels=new Set(rows.map(r=>r.label));
if(labels.size!==3) throw new Error("labels not distinct: "+[...labels]);
const ans=JSON.parse(fs.readFileSync("answer.json","utf8"));
const keys=Object.keys(ans);
console.log(JSON.stringify(rows));
console.log("labels distinct:",labels.size,"sum:",sum);
console.log("answer.json keys:",JSON.stringify(keys),"total:",ans.total,"typeof:",typeof ans.total);
if(keys.length!==1||keys[0]!=="total") throw new Error("unexpected keys");
if(typeof ans.total!=="number") throw new Error("total not numeric");
if(ans.total!==sum) throw new Error("total mismatch "+ans.total+" != "+sum);
if(!Number.isFinite(ans.total)) throw new Error("total not finite");
console.log("VERIFY PASS total="+ans.total);
'

